import type { Question } from '../../lib/types'

export const analytics_streaming_questions: Question[] = [
  { id: 'd3-ana-001', domain: 3, topics: ['Kinesis Data Streams', 'shards', 'throughput'], type: 'single', stem: 'A Kinesis Data Stream receives 8,000 records/second at 1 KB each (8 MB/s ingestion). How many shards are required?', options: [{ id: 'A', text: '4 shards' }, { id: 'B', text: '16 shards' }, { id: 'C', text: '1 shard handles unlimited throughput' }, { id: 'D', text: '8 shards' }], correct: ['D'], explanation: 'Each Kinesis shard: 1 MB/s write (1,000 records/s) and 2 MB/s read. At 8 MB/s write throughput, exactly 8 shards are needed. Always round up for safety margins.', distractors: { A: '4 shards = 4 MB/s — insufficient for 8 MB/s.', C: '16 shards would be double the needed capacity — wasteful.', D: 'Kinesis has per-shard limits — throughput scales by adding shards.' } },
  { id: 'd3-ana-002', domain: 3, topics: ['Kinesis Data Firehose', 'managed delivery', 'S3'], type: 'single', stem: 'A company needs to ingest streaming data and load it into S3 for analysis — with automatic batching, compression, and error handling — without writing consumer code. What service provides this?', options: [{ id: 'A', text: 'Amazon Data Firehose (formerly Kinesis Data Firehose)' }, { id: 'B', text: 'Kinesis Data Streams with a custom Lambda consumer' }, { id: 'C', text: 'MSK (Managed Kafka) with consumer app' }, { id: 'D', text: 'SQS with S3 event notifications' }], correct: ['A'], explanation: 'Amazon Data Firehose is serverless — no consumer code needed. Ingests streaming data, buffers (by size or time), optionally transforms with Lambda, then delivers to S3, Redshift, OpenSearch, Splunk, or HTTP endpoints. Handles compression (gzip, Snappy), conversion (Parquet, ORC), and encryption.', distractors: { A: 'Kinesis Data Streams + Lambda requires writing and managing consumer code.', C: 'SQS is for message queuing — not stream-to-S3 delivery with buffering and transformation.', D: 'MSK requires running Kafka consumers — not fully managed delivery.' } },
  { id: 'd3-ana-003', domain: 3, topics: ['Redshift', 'cluster', 'columnar'], type: 'single', stem: 'A data warehouse query scans a table with 50 columns but only reads 3 columns. A row-based database reads all 50 columns. What storage format does Redshift use to optimize this?', options: [{ id: 'A', text: 'Document store format' }, { id: 'B', text: 'Columnar storage' }, { id: 'C', text: 'Row-based storage like RDS' }, { id: 'D', text: 'Key-value compressed format' }], correct: ['B'], explanation: 'Redshift stores data in columnar format. Queries reading 3 out of 50 columns only read ~6% of the data. Combined with column-level compression, this dramatically reduces I/O and improves analytical query performance.', distractors: { A: 'Row-based storage reads entire rows — inefficient for analytical queries that touch few columns.', C: 'Document stores are for semi-structured data — not columnar OLAP.', D: 'Key-value storage is for lookup by key — not columnar analytical queries.' } },
  { id: 'd3-ana-004', domain: 3, topics: ['Athena', 'S3', 'serverless SQL'], type: 'single', stem: 'A data team needs to query log files stored in S3 using SQL — without loading data into a database. They only query a subset of data occasionally. What service minimizes cost and operational overhead?', options: [{ id: 'A', text: 'Redshift with S3 COPY' }, { id: 'B', text: 'EMR with Hive' }, { id: 'C', text: 'Amazon Athena' }, { id: 'D', text: 'RDS PostgreSQL with S3 import' }], correct: ['C'], explanation: 'Athena queries S3 directly using SQL (Presto-based). No infrastructure, no clusters. Charges $5/TB scanned. Use Parquet/ORC format and partition data to minimize scan cost. Perfect for ad-hoc analysis on data already in S3.', distractors: { A: 'RDS requires loading data into a managed database — adds cost and latency for data already in S3.', C: 'Redshift COPY loads data into Redshift — adds ongoing cluster costs for occasional queries.', D: 'EMR requires cluster management — more operational overhead for simple S3 SQL queries.' } },
  { id: 'd3-ana-005', domain: 3, topics: ['EMR', 'big data', 'Hadoop/Spark'], type: 'single', stem: 'A team needs to run complex distributed data processing (Apache Spark ML pipelines, Hadoop MapReduce) on petabyte-scale datasets. What AWS service manages the cluster infrastructure?', options: [{ id: 'A', text: 'AWS Glue (serverless, but limited to ETL transforms)' }, { id: 'B', text: 'Redshift (single-cluster analytics)' }, { id: 'C', text: 'Kinesis Analytics' }, { id: 'D', text: 'Amazon EMR' }], correct: ['D'], explanation: 'EMR provides managed clusters for Apache Hadoop, Spark, Hive, HBase, Presto, and more. Runs on EC2 (Spot for savings), EKS, or Serverless mode. Ideal for complex distributed processing workloads beyond ETL — ML training, graph processing, custom Spark jobs.', distractors: { A: 'AWS Glue handles ETL workloads with Spark — but EMR provides the full ecosystem for ML and custom Spark applications.', C: 'Kinesis Analytics (Managed Service for Apache Flink) is for real-time streaming — not batch big data processing.', D: 'Redshift is for structured analytical queries — not distributed processing pipelines.' } },
  { id: 'd3-ana-006', domain: 3, topics: ['OpenSearch', 'full-text search', 'Kibana'], type: 'single', stem: 'An application needs full-text search with real-time dashboards for log analysis. Which service provides Elasticsearch/OpenSearch compatible search with built-in visualization?', options: [{ id: 'A', text: 'Amazon OpenSearch Service' }, { id: 'B', text: 'CloudWatch Logs Insights' }, { id: 'C', text: 'Amazon RDS with full-text indexes' }, { id: 'D', text: 'Amazon Redshift for log analysis' }], correct: ['A'], explanation: 'Amazon OpenSearch Service (formerly Elasticsearch Service) provides managed OpenSearch/Elasticsearch clusters with OpenSearch Dashboards for real-time visualization. Supports full-text search, log analytics, time-series analysis, and complex aggregations.', distractors: { A: 'RDS full-text search has limited capabilities — not designed for log analytics at scale.', C: 'Redshift is for structured SQL analytics — not optimized for unstructured full-text search.', D: 'CloudWatch Logs Insights queries CloudWatch logs — not a general-purpose search platform for application logs.' } },
  { id: 'd3-ana-007', domain: 3, topics: ['Kinesis Data Streams', 'retention', 'replay'], type: 'single', stem: 'A streaming application needs to reprocess the last 7 days of data after a bug fix. Kinesis Data Streams default retention is 24 hours. What configuration enables 7-day replay?', options: [{ id: 'A', text: 'Archive to S3 and reprocess from S3' }, { id: 'B', text: 'Use Kinesis Data Firehose for longer retention' }, { id: 'C', text: 'Enable long-term retention' }, { id: 'D', text: 'Kinesis cannot replay data' }], correct: ['C'], explanation: 'Kinesis Data Streams supports extended retention from 24 hours up to 365 days. Configure the retention period on the stream. Consumers can read from the TRIM_HORIZON iterator to replay all available data. Extended retention has additional hourly cost per shard.', distractors: { B: 'Firehose delivers data to destinations — it doesn\'t expose the data for reprocessing in the same way as Kinesis streams.', C: 'S3 archiving works but requires ETL pipeline setup — Kinesis extended retention is simpler for replay use cases.', D: 'Kinesis absolutely supports data replay — consumers can reset to TRIM_HORIZON to read from the oldest available record.' } },
  { id: 'd3-ana-008', domain: 3, topics: ['Glue', 'ETL', 'data catalog'], type: 'single', stem: 'Data engineers need to discover S3 data schemas automatically and maintain a central metadata catalog for Athena and Redshift Spectrum to query. What service provides automated schema discovery and metadata management?', options: [{ id: 'A', text: 'AWS Glue Data Catalog with Glue Crawlers' }, { id: 'B', text: 'DynamoDB for metadata storage' }, { id: 'C', text: 'RDS Information Schema' }, { id: 'D', text: 'AWS Config for resource discovery' }], correct: ['A'], explanation: 'AWS Glue Crawlers scan S3, RDS, and other sources to infer data schemas and store metadata in the Glue Data Catalog. Athena, Redshift Spectrum, EMR, and other services query the catalog as the central metadata repository.', distractors: { A: 'AWS Config tracks AWS resource configurations — not data schema discovery.', C: 'RDS Information Schema is for RDS database metadata — not S3 data schemas.', D: 'DynamoDB could store metadata but doesn\'t integrate with Athena/Redshift Spectrum as a catalog.' } },
  { id: 'd3-ana-009', domain: 3, topics: ['Redshift', 'Spectrum', 'S3 federated query'], type: 'single', stem: 'A Redshift cluster has structured data in Redshift tables. Related historical data lives in S3 as Parquet files. A query needs to JOIN Redshift tables with S3 data. What feature enables this?', options: [{ id: 'A', text: 'COPY the S3 data into Redshift first' }, { id: 'B', text: 'Use Athena to query S3, then Redshift for the table data' }, { id: 'C', text: 'Replicate S3 data to RDS and JOIN there' }, { id: 'D', text: 'Redshift Spectrum' }], correct: ['D'], explanation: 'Redshift Spectrum extends Redshift queries to S3. Define an external table pointing to S3 data (using Glue Data Catalog). Query JOIN Redshift local tables with Spectrum external tables in a single SQL statement. Redshift pushes down computation to the Spectrum layer.', distractors: { A: 'COPY loads all historical data into Redshift — expensive in storage and time for large datasets.', C: 'Two separate queries with application-level JOIN is complex and doesn\'t leverage Redshift optimization.', D: 'Replicating to RDS adds another database layer and costs.' } },
  { id: 'd3-ana-010', domain: 3, topics: ['Kinesis', 'enhanced fan-out', 'consumers'], type: 'single', stem: 'Five Lambda functions all consume from the same Kinesis shard. Each shard provides 2 MB/s read throughput shared among consumers using standard GetRecords (polling). How can each consumer get 2 MB/s independently?', options: [{ id: 'A', text: 'Add more shards' }, { id: 'B', text: 'Register Enhanced Fan-Out consumers' }, { id: 'C', text: 'Use Kinesis Data Firehose instead' }, { id: 'D', text: 'Increase polling frequency' }], correct: ['B'], explanation: 'Enhanced Fan-Out provides dedicated 2 MB/s per consumer per shard using HTTP/2 server push. Standard consumers share 2 MB/s per shard. With 5 Enhanced Fan-Out consumers, each gets 2 MB/s independently — total output bandwidth from the shard is effectively 10 MB/s.', distractors: { A: 'More shards increase write throughput — not per-consumer read throughput from the same shard.', C: 'Firehose delivers to destinations (S3/Redshift) — not a multi-consumer fan-out solution.', D: 'More frequent polling increases calls and costs — doesn\'t increase the shared 2 MB/s total read bandwidth.' } },
  { id: 'd3-ana-011', domain: 3, topics: ['MSK', 'Managed Kafka', 'streaming'], type: 'single', stem: 'An organization already uses Apache Kafka on-premises and wants to migrate to a managed AWS service without changing producer/consumer code. What service provides fully managed Kafka?', options: [{ id: 'A', text: 'Amazon SQS with Kafka bridge' }, { id: 'B', text: 'AWS IoT Core for streaming' }, { id: 'C', text: 'Amazon MSK (Managed Streaming for Apache Kafka)' }, { id: 'D', text: 'Amazon Kinesis Data Streams (Kafka-compatible API)' }], correct: ['C'], explanation: 'Amazon MSK runs fully managed Apache Kafka. Producers and consumers use the standard Kafka client libraries — no API changes. AWS handles broker provisioning, patching, monitoring, and failure recovery. Also offers MSK Serverless.', distractors: { A: 'Kinesis uses its own API (PutRecord/GetRecords) — not Kafka-compatible; code changes required.', C: 'SQS has no Kafka bridge — fundamentally different service.', D: 'IoT Core is for IoT device messaging — not Kafka workload migration.' } },
  { id: 'd3-ana-012', domain: 3, topics: ['Athena', 'Parquet', 'cost optimization'], type: 'single', stem: 'An Athena query scans 1 TB of CSV data monthly at $5/TB = $5/month. How can scan cost be reduced significantly?', options: [{ id: 'A', text: 'Schedule queries during off-peak hours' }, { id: 'B', text: 'Compress CSV with gzip' }, { id: 'C', text: 'Use a larger Athena engine version' }, { id: 'D', text: 'Convert data from CSV to Parquet and partition by query filters (e.g., date)' }], correct: ['D'], explanation: 'Two key Athena cost optimizations: (1) Parquet/ORC columnar format — only scanned columns are read. (2) Partition pruning — Athena only scans relevant S3 prefixes when queries include partition filters. Combined, these can reduce scan cost by 90-99%.', distractors: { A: 'Athena engine version affects query performance/features — not scan cost.', C: 'Athena charges by data scanned — query time doesn\'t affect cost.', D: 'gzip compression reduces storage cost and scan bytes but not as effectively as Parquet column projection + partition pruning.' } },
  { id: 'd3-ana-013', domain: 3, topics: ['QuickSight', 'BI', 'visualization'], type: 'single', stem: 'A business team needs self-service dashboards and interactive visualizations connected to Redshift, Athena, and S3 data — without managing BI server infrastructure. What AWS service provides this?', options: [{ id: 'A', text: 'Custom EC2-hosted Tableau' }, { id: 'B', text: 'Kibana (OpenSearch Dashboards)' }, { id: 'C', text: 'Amazon QuickSight' }, { id: 'D', text: 'Amazon Managed Grafana' }], correct: ['C'], explanation: 'Amazon QuickSight is a serverless BI service. Connects to Redshift, Athena, RDS, S3, and third-party sources. Supports dashboards, ML insights (anomaly detection, forecasting), Q (natural language queries). No infrastructure to manage.', distractors: { A: 'OpenSearch Dashboards (Kibana) is for log/search analytics — not general BI across multiple AWS data sources.', C: 'Managed Grafana is for operational/infrastructure metrics — not business intelligence reporting.', D: 'EC2-hosted Tableau requires infrastructure management and licensing overhead.' } },
  { id: 'd3-ana-014', domain: 3, topics: ['Kinesis Data Analytics', 'Flink', 'real-time'], type: 'single', stem: 'A fraud detection system needs to analyze transaction streams in real-time with complex event processing, windowing functions, and stateful computations. What managed service enables SQL or Java/Python streaming analytics?', options: [{ id: 'A', text: 'Kinesis Data Firehose' }, { id: 'B', text: 'Amazon Managed Service for Apache Flink (formerly Kinesis Data Analytics)' }, { id: 'C', text: 'AWS Lambda with Kinesis trigger' }, { id: 'D', text: 'Amazon EMR with Spark Structured Streaming' }], correct: ['B'], explanation: 'Managed Service for Apache Flink runs Apache Flink applications for real-time stream processing. Supports SQL (Table API) and Java/Python/Scala. Features: event-time processing, windowing, stateful operations, joins across streams. Integrates with Kinesis and MSK.', distractors: { A: 'Firehose is for delivery (ingestion to S3/Redshift) — not real-time processing with stateful analytics.', C: 'Lambda with Kinesis trigger works for simple processing — not complex stateful windowing and joins.', D: 'EMR Spark Streaming works but requires cluster management — Managed Flink is fully managed for streaming.' } },
  { id: 'd3-ana-015', domain: 3, topics: ['Redshift', 'AQUA', 'performance'], type: 'single', stem: 'A Redshift RA3 cluster query scans petabytes of data in S3 (Redshift Managed Storage). What Redshift feature pushes query execution to the storage layer for faster results?', options: [{ id: 'A', text: 'AQUA (Advanced Query Accelerator)' }, { id: 'B', text: 'Redshift Spectrum' }, { id: 'C', text: 'Redshift workload management (WLM)' }, { id: 'D', text: 'Redshift concurrency scaling' }], correct: ['A'], explanation: 'AQUA is a distributed hardware cache that sits between Redshift compute and S3 storage. It runs query operations (filtering, aggregations) directly in the storage layer on custom Nitro-based hardware. Reduces data transferred to compute nodes — speeds up queries up to 10x.', distractors: { A: 'Concurrency scaling adds query processing capacity during peaks — not storage-layer query pushdown.', C: 'Spectrum queries S3 data via external tables — AQUA accelerates Redshift managed storage queries.', D: 'WLM manages query queues and priorities — not hardware-level query acceleration.' } },
  { id: 'd3-ana-016', domain: 3, topics: ['Lake Formation', 'data lake security'], type: 'single', stem: 'A company has a data lake on S3 with Glue Data Catalog. They need fine-grained column-level and row-level access control — different teams should query different subsets of data. What service provides this governance layer?', options: [{ id: 'A', text: 'S3 bucket policies per team' }, { id: 'B', text: 'IAM roles per data column' }, { id: 'C', text: 'Separate S3 buckets per team' }, { id: 'D', text: 'AWS Lake Formation' }], correct: ['D'], explanation: 'Lake Formation provides fine-grained access control at database, table, column, row, and cell levels. Integrates with the Glue Data Catalog. When users query via Athena, Redshift Spectrum, or EMR, Lake Formation permissions are enforced — limiting what columns/rows they can see.', distractors: { A: 'S3 bucket policies control object-level access — not SQL column/row-level filtering.', C: 'IAM doesn\'t support column/row level SQL access control — Lake Formation translates permissions to query-level filters.', D: 'Separate buckets provide bucket-level isolation — doesn\'t enable sharing with selective column visibility.' } },
  { id: 'd3-ana-017', domain: 3, topics: ['DataSync', 'analytics migration'], type: 'single', stem: 'A data team needs to migrate 50 TB of on-premises analytics data to S3 with integrity verification (checksums) and scheduling for ongoing sync. What service automates this?', options: [{ id: 'A', text: 'AWS DataSync' }, { id: 'B', text: 'AWS Snowball for one-time migration' }, { id: 'C', text: 'Storage Gateway File Gateway' }, { id: 'D', text: 'Direct S3 upload with multipart' }], correct: ['A'], explanation: 'DataSync automates data migration to S3, EFS, and FSx. Agent installed on-premises uses optimized protocols (not standard SMB/NFS). Performs automatic checksum verification, scheduling, filtering, and task reporting. Good for both one-time migration and ongoing sync.', distractors: { A: 'Snowball is for offline bulk transfers (typically 10+ TB where network is impractical) — DataSync is for network-based migration with ongoing sync.', C: 'Direct S3 multipart upload doesn\'t provide checksums, scheduling, or differential sync.', D: 'Storage Gateway File Gateway presents NFS/SMB for ongoing access — not a data migration tool.' } },
  { id: 'd3-ana-018', domain: 3, topics: ['Kinesis', 'producer', 'batching'], type: 'single', stem: 'A Kinesis producer sends individual records one at a time using PutRecord. This generates many API calls and costs more. What API reduces API call volume?', options: [{ id: 'A', text: 'Increase shard count' }, { id: 'B', text: 'Use PutRecords API' }, { id: 'C', text: 'Switch to Kinesis Data Firehose for batching' }, { id: 'D', text: 'Use Enhanced Fan-Out' }], correct: ['B'], explanation: 'PutRecords sends up to 500 records in a single API call (up to 5 MB total). Reduces API call overhead, improves throughput, and reduces per-call latency vs. individual PutRecord calls. The Kinesis Producer Library (KPL) automatically batches records for efficiency.', distractors: { A: 'Firehose batches delivery to destinations — not a replacement for efficient Kinesis stream producers.', C: 'More shards increase stream throughput capacity — don\'t reduce producer API calls.', D: 'Enhanced Fan-Out is for consumers (read side) — not producer optimization.' } },
  { id: 'd3-ana-019', domain: 3, topics: ['Athena', 'partitions', 'performance'], type: 'single', stem: 'An Athena query on S3 data takes 2 minutes because it scans all data regardless of the date filter in the WHERE clause. The data is stored in S3 prefixes by date (s3://bucket/year=2024/month=07/). What enables Athena to skip irrelevant partitions?', options: [{ id: 'A', text: 'Partition projection or register partitions in Glue Data Catalog' }, { id: 'B', text: 'Increase Athena DPU allocation' }, { id: 'C', text: 'Store data in RDS for indexed queries' }, { id: 'D', text: 'Add an index to the Athena table' }], correct: ['A'], explanation: 'Athena partition pruning requires partitions to be defined. Use Glue Crawlers to register partitions, run MSCK REPAIR TABLE, use Partition Projection (auto-generates partition metadata without Glue), or use AWS Glue catalog. Athena only reads S3 prefixes matching the query\'s partition filters.', distractors: { A: 'Athena doesn\'t have traditional indexes — partitioning serves the same purpose for S3 data.', C: 'Athena doesn\'t have manual DPU allocation — it\'s serverless.', D: 'RDS is inappropriate for data already in S3 as part of a data lake.' } },
  { id: 'd3-ana-020', domain: 3, topics: ['Redshift', 'workload management', 'concurrency'], type: 'single', stem: 'A Redshift cluster has analytics queries (long-running, large scans) competing with dashboard queries (short, small, need low latency). How can these be isolated?', options: [{ id: 'A', text: 'Scale the Redshift cluster vertically' }, { id: 'B', text: 'Use separate Redshift clusters for each workload' }, { id: 'C', text: 'Redshift WLM (Workload Management)' }, { id: 'D', text: 'Run analytics queries at night only' }], correct: ['C'], explanation: 'Redshift WLM queues separate workloads. Configure a high-memory/low-concurrency queue for analytics and a low-memory/high-concurrency queue for dashboards. Use automatic WLM (ML-based) or manual WLM. Prevents long queries from blocking short interactive queries.', distractors: { A: 'Separate clusters work but are expensive — WLM provides isolation within one cluster.', C: 'Time-based separation limits analytics agility — WLM provides real-time isolation.', D: 'Vertical scaling increases total resources — doesn\'t prevent workload interference.' } },
  { id: 'd3-ana-021', domain: 3, topics: ['Timestream', 'time-series', 'IoT'], type: 'single', stem: 'An IoT system generates 100,000 time-series data points per second from industrial sensors. Each data point has a timestamp, device ID, and metric value. What purpose-built database handles time-series at this scale?', options: [{ id: 'A', text: 'RDS with time-series partitioning' }, { id: 'B', text: 'Amazon Timestream' }, { id: 'C', text: 'DynamoDB with timestamp as sort key' }, { id: 'D', text: 'OpenSearch with time-based indexes' }], correct: ['B'], explanation: 'Amazon Timestream is built specifically for time-series workloads. Handles trillions of events per day, automatic tiered storage (hot in-memory, warm/cold on SSD/magnetic), built-in time-series functions (smoothing, interpolation), and automatic data lifecycle management.', distractors: { A: 'DynamoDB can handle time-series but lacks built-in time-series functions, automatic tiering, and is more expensive at high scale.', C: 'RDS requires manual partitioning management and doesn\'t scale as easily for millions of events per second.', D: 'OpenSearch works for time-series analytics (ELK stack) but isn\'t a purpose-built time-series storage engine.' } },
  { id: 'd3-ana-022', domain: 3, topics: ['Redshift', 'concurrency scaling', 'burst'], type: 'single', stem: 'A Redshift cluster handles up to 50 concurrent queries normally. During quarterly business reviews, 200 users run queries simultaneously, causing queue backups. What handles this burst?', options: [{ id: 'A', text: 'Redshift Concurrency Scaling' }, { id: 'B', text: 'Route burst queries to Athena' }, { id: 'C', text: 'Use Redshift RA3 nodes for more compute' }, { id: 'D', text: 'Manually resize the Redshift cluster before each review' }], correct: ['A'], explanation: 'Concurrency Scaling automatically adds query processing capacity when cluster concurrency increases. Read queries route to additional transient clusters. The first 1 hour of concurrency scaling per 24 hours is free. Pay-per-second for additional usage.', distractors: { A: 'Manual resize is disruptive (cluster goes into read-only during elastic resize) — concurrency scaling is automatic.', C: 'RA3 nodes have larger storage — concurrency scaling is for throughput during spikes.', D: 'Athena queries S3 — doesn\'t have access to Redshift-managed data.' } },
  { id: 'd3-ana-023', domain: 3, topics: ['Kinesis', 'partition key', 'hot shard'], type: 'single', stem: 'A Kinesis stream has 10 shards but one shard is consistently at 100% utilization while others are idle. All records for the most popular user are going to the same shard. What causes this?', options: [{ id: 'A', text: 'The stream needs more shards' }, { id: 'B', text: 'The consumer is too slow' }, { id: 'C', text: 'Kinesis shard limits are too low' }, { id: 'D', text: 'Hot partition' }], correct: ['D'], explanation: 'Kinesis uses the partition key hash to route records to shards deterministically. If many records share the same partition key (e.g., user ID for one popular user), all go to the same shard, creating a hot partition. Solution: use high-cardinality, randomly distributed partition keys.', distractors: { A: 'More shards doesn\'t help if all records hash to the same shard — the partition key strategy must change.', C: 'Slow consumers affect read lag — doesn\'t cause a single shard to be 100% utilized on writes.', D: 'Shard limits can be increased — but the hot partition issue is about partition key distribution, not total shard count.' } },
  { id: 'd3-ana-024', domain: 3, topics: ['EMR', 'Spot instances', 'cost'], type: 'single', stem: 'An EMR Spark job processes data in 2 hours and runs nightly. What instance configuration minimizes cost while tolerating occasional interruptions?', options: [{ id: 'A', text: 'On-Demand for master/core nodes (stability) + Spot instances for task nodes (interruptible worker capacity)' }, { id: 'B', text: 'Fargate for EMR' }, { id: 'C', text: 'On-Demand EC2 for all nodes' }, { id: 'D', text: 'Spot instances for all nodes including master' }], correct: ['A'], explanation: 'Best practice: On-Demand for master (single point of failure — interruption kills the cluster) and core nodes (HDFS data stored here). Spot for task nodes (stateless compute — interruption just returns tasks to other nodes). Task nodes can be 60-90% cheaper on Spot.', distractors: { A: 'On-Demand for all nodes costs 2-5x more than mixed fleet.', C: 'Spot for master node risks cluster termination — if master is interrupted, the entire job fails.', D: 'EMR Serverless is the serverless option — Fargate is for ECS/EKS containers.' } },
  { id: 'd3-ana-025', domain: 3, topics: ['Glue', 'job bookmarks', 'incremental'], type: 'single', stem: 'An AWS Glue ETL job processes new S3 files daily. Without modification, the job reprocesses all S3 files every run. What Glue feature processes only new data?', options: [{ id: 'A', text: 'S3 event notifications to trigger Glue' }, { id: 'B', text: 'Glue workflows with conditional triggers' }, { id: 'C', text: 'Glue Job Bookmarks' }, { id: 'D', text: 'S3 object versioning' }], correct: ['C'], explanation: 'Glue Job Bookmarks persist processing state (e.g., the last modified S3 object timestamp or JDBC timestamp). On the next run, Glue starts from the bookmark — only processing new records. Eliminates redundant reprocessing of already-transformed data.', distractors: { A: 'S3 event notifications trigger Glue on file arrival — doesn\'t track what Glue has already processed.', C: 'Glue workflows orchestrate multiple jobs with conditions — not incremental data tracking within a job.', D: 'S3 versioning maintains object versions — doesn\'t tell Glue which objects have been processed.' } },
  { id: 'd3-ana-026', domain: 3, topics: ['Redshift', 'materialized views', 'performance'], type: 'single', stem: 'A Redshift dashboard repeatedly runs the same complex aggregation query over 100 GB of data every 5 minutes. The query takes 30 seconds each time. What reduces repeated computation?', options: [{ id: 'A', text: 'Create a Materialized View' }, { id: 'B', text: 'Use Redshift Concurrency Scaling' }, { id: 'C', text: 'Move data to ElastiCache' }, { id: 'D', text: 'Enable Redshift result caching' }], correct: ['D'], explanation: 'Redshift result caching stores query results. If the same query is re-executed and the underlying data hasn\'t changed, Redshift returns the cached result instantly — no recomputation. Materialized views also work but result caching is simpler for identical repeated queries.', distractors: { B: 'Materialized views work for incremental computation but require explicit creation and maintenance — result caching is automatic for identical queries.', C: 'Moving data to ElastiCache is complex and inappropriate for SQL aggregations.', D: 'Concurrency Scaling adds capacity for concurrent queries — doesn\'t eliminate redundant computation.' } },
  { id: 'd3-ana-027', domain: 3, topics: ['Kinesis Firehose', 'Lambda transform', 'ETL'], type: 'single', stem: 'A Kinesis Data Firehose stream delivers raw JSON records to S3. Before delivery, records need to be enriched with a geolocation lookup. How is this transformation added?', options: [{ id: 'A', text: 'Post-process files in S3 after delivery' }, { id: 'B', text: 'Use Glue to transform before Firehose ingestion' }, { id: 'C', text: 'Add a transformation rule in Firehose configuration' }, { id: 'D', text: 'Configure a Lambda function as a Firehose data transformation' }], correct: ['D'], explanation: 'Firehose supports inline Lambda transformation. Configure a Lambda function ARN in the Firehose delivery stream. Firehose invokes Lambda with batches (up to 3 MB), receives transformed records, and delivers them. The function can enrich, filter, or format records.', distractors: { A: 'Firehose has limited native transformations (format conversion to Parquet/ORC) — custom logic requires Lambda.', C: 'Post-processing adds operational complexity — Firehose Lambda transformation handles this inline.', D: 'Glue upstream from Firehose is an architectural option but less direct than inline Lambda transformation.' } },
  { id: 'd3-ana-028', domain: 3, topics: ['OpenSearch', 'cross-cluster search', 'scaling'], type: 'single', stem: 'An OpenSearch domain is at maximum storage capacity. Instead of migrating to a larger domain, what allows querying data distributed across multiple OpenSearch domains?', options: [{ id: 'A', text: 'Reindex to a new larger domain' }, { id: 'B', text: 'Increase domain storage (EBS expansion)' }, { id: 'C', text: 'OpenSearch cross-cluster search' }, { id: 'D', text: 'S3 tiering for old indices' }], correct: ['C'], explanation: 'OpenSearch cross-cluster search (CCS) allows a coordinating cluster to search across multiple remote OpenSearch domains. Create a new domain for new data, archive old data to the original domain, and query both from the coordinating domain with a federated search.', distractors: { A: 'EBS expansion is possible (up to 3 PiB per domain) — but cross-cluster search solves the architectural scaling problem.', C: 'UltraWarm and Cold tiers (S3-backed) on OpenSearch handle less-frequently accessed indices — but CCS handles querying across separate domains.', D: 'Reindexing to a larger domain requires downtime and data transfer — CCS is live without data migration.' } },
  { id: 'd3-ana-029', domain: 3, topics: ['EMR Serverless', 'Glue', 'comparison'], type: 'single', stem: 'A team runs occasional Spark ETL jobs and wants serverless execution without managing clusters. What two options provide serverless Spark execution?', options: [{ id: 'A', text: 'Only AWS Glue (serverless)' }, { id: 'B', text: 'AWS Glue (serverless ETL, Spark/Python/Scala) and Amazon EMR Serverless (serverless Spark/Hive, more control)' }, { id: 'C', text: 'Only EMR on EKS' }, { id: 'D', text: 'Only Lambda with PySpark' }], correct: ['B'], explanation: 'AWS Glue: serverless Spark/Python ETL with managed jobs, crawlers, data catalog. EMR Serverless: serverless EMR that runs Spark and Hive applications without cluster management — more configuration flexibility than Glue. Both eliminate cluster provisioning.', distractors: { A: 'Glue is one option — EMR Serverless is also serverless and provides more Apache ecosystem compatibility.', C: 'EMR on EKS runs on Kubernetes nodes — requires EKS cluster management.', D: 'Lambda supports Python but has a 15-min timeout and 10 GB memory limit — not suitable for large Spark jobs.' } },
  { id: 'd3-ana-030', domain: 3, topics: ['Kinesis', 'ordering', 'sequence number'], type: 'single', stem: 'A Kinesis consumer needs to process records in strict chronological order within a partition key\'s data. How does Kinesis ensure this?', options: [{ id: 'A', text: 'Kinesis guarantees global ordering across all shards' }, { id: 'B', text: 'Consumers must sort records by timestamp after reading' }, { id: 'C', text: 'Use SQS FIFO for ordering guarantees' }, { id: 'D', text: 'Kinesis guarantees ordering within a shard' }], correct: ['D'], explanation: 'Kinesis guarantees ordering within a shard via sequence numbers (monotonically increasing). Records with the same partition key always go to the same shard, so they are processed in order. No ordering guarantee across different shards.', distractors: { A: 'Global ordering across shards is not guaranteed — only within a single shard.', C: 'Consumer-side sorting adds latency and requires buffering — Kinesis ordering within a shard eliminates this need.', D: 'SQS FIFO provides ordering within a message group — an alternative for queue-based messaging but not Kinesis streams.' } },
  { id: 'd3-ana-031', domain: 3, topics: ['Redshift', 'distribution keys', 'performance'], type: 'single', stem: 'A Redshift JOIN between a 1 TB fact table and a 100 MB dimension table is slow due to data redistribution during the JOIN. What distribution strategy eliminates the redistribution?', options: [{ id: 'A', text: 'Distribute the small dimension table using ALL distribution' }, { id: 'B', text: 'Distribute both tables with KEY on the JOIN column' }, { id: 'C', text: 'Use AUTO distribution and let Redshift decide' }, { id: 'D', text: 'Use EVEN distribution for both tables' }], correct: ['A'], explanation: 'Redshift ALL distribution copies the entire table to every compute node. For small dimension tables, this eliminates broadcast redistribution during JOINs. The fact table can use KEY or EVEN distribution. Trade-off: more storage, but JOIN performance dramatically improves.', distractors: { A: 'KEY distribution on both tables using the JOIN key co-locates matching rows — also effective but may not be optimal if the fact table has skew.', C: 'EVEN distribution spreads rows round-robin — JOIN still requires redistribution.', D: 'AUTO distribution is good for many cases — but for known small dimension tables, ALL is explicitly the right choice.' } },
  { id: 'd3-ana-032', domain: 3, topics: ['Glue', 'DynamicFrame', 'schema evolution'], type: 'single', stem: 'A Glue ETL job reads JSON records where the schema varies between records (some have extra fields, some have missing fields). What Glue abstraction handles schema variability better than Spark DataFrames?', options: [{ id: 'A', text: 'Spark DataFrame with nullable schema' }, { id: 'B', text: 'JSON Schema validation before processing' }, { id: 'C', text: 'AWS Glue DynamicFrame' }, { id: 'D', text: 'Store raw JSON without schema enforcement' }], correct: ['C'], explanation: 'Glue DynamicFrame is a distributed data abstraction where each record can have different schema. Handles semi-structured data with schema variations gracefully. ChoiceType handles fields that appear with different data types. Convert to DataFrame for standard Spark operations when needed.', distractors: { A: 'Spark DataFrames require a fixed schema — schema variations cause failures or require complex custom handling.', C: 'Schema validation rejects invalid records — DynamicFrame accommodates variations.', D: 'Unstructured raw storage doesn\'t leverage Glue\'s transformation capabilities.' } },
  { id: 'd3-ana-033', domain: 3, topics: ['Athena', 'query federation', 'cross-source'], type: 'single', stem: 'A team wants to query data from RDS, DynamoDB, and S3 together in a single Athena SQL query. What enables Athena to query multiple data sources beyond S3?', options: [{ id: 'A', text: 'Athena Query Federation with data source connectors' }, { id: 'B', text: 'Copy all data to S3 first' }, { id: 'C', text: 'Use AWS Glue to join sources before Athena' }, { id: 'D', text: 'Athena can only query S3' }], correct: ['A'], explanation: 'Athena Query Federation uses Lambda-based data source connectors to query non-S3 sources inline. AWS provides connectors for RDS, DynamoDB, Redshift, CloudWatch, and more. A federated query can JOIN S3 data with RDS and DynamoDB in a single SQL statement.', distractors: { A: 'Athena Query Federation extends Athena beyond S3 — this is now a core Athena feature.', C: 'Copying all data to S3 adds ETL complexity and storage cost — federation queries in-place.', D: 'Glue federation is another option — Athena federation provides SQL-level cross-source JOINs more directly.' } },
  { id: 'd3-ana-034', domain: 3, topics: ['MSK', 'auto scaling', 'storage'], type: 'single', stem: 'An MSK cluster is running out of disk storage as Kafka topic retention data grows. What feature automatically adds storage capacity?', options: [{ id: 'A', text: 'Manually add MSK broker nodes' }, { id: 'B', text: 'Reduce Kafka topic retention' }, { id: 'C', text: 'Enable MSK tiered storage to S3' }, { id: 'D', text: 'MSK auto-expand storage' }], correct: ['D'], explanation: 'MSK supports automatic storage expansion. Configure the maximum storage size and the utilization threshold (default 85%). MSK automatically scales up EBS storage per broker when threshold is reached — no downtime, no manual intervention.', distractors: { A: 'Adding broker nodes increases partition capacity but doesn\'t expand per-broker storage automatically.', C: 'MSK tiered storage offloads older data to S3 — valid for cost management but different from auto-expanding hot storage.', D: 'Reducing retention loses data — not a solution for legitimate storage growth.' } },
  { id: 'd3-ana-035', domain: 3, topics: ['Kinesis', 'shard splitting', 'scaling'], type: 'single', stem: 'A Kinesis stream is reaching its shard write limits. How can the stream\'s throughput be increased?', options: [{ id: 'A', text: 'Use Kinesis Data Firehose instead' }, { id: 'B', text: 'Reduce the record size' }, { id: 'C', text: 'Split shards' }, { id: 'D', text: 'Enable enhanced fan-out' }], correct: ['C'], explanation: 'Kinesis streams can be scaled by splitting shards (increases throughput) or merging them (decreases throughput, reduces cost). Shard splitting divides one shard into two, doubling the throughput for that partition key range. Also consider Kinesis scaling policies to automate this.', distractors: { A: 'Smaller records increase records/second but per-shard MB/s limit still applies — splitting increases both limits.', C: 'Enhanced fan-out improves consumer read throughput — not producer write throughput.', D: 'Firehose is for delivery to destinations — not a replacement for Kinesis Data Streams for streaming applications.' } },
  { id: 'd3-ana-036', domain: 3, topics: ['OpenSearch', 'UltraWarm', 'cold storage'], type: 'single', stem: 'An OpenSearch domain stores 30 days of logs on SSD-backed hot storage. Logs older than 7 days are rarely queried but must be retained for 90 days. What reduces storage cost for older logs?', options: [{ id: 'A', text: 'Export to S3 and delete from OpenSearch' }, { id: 'B', text: 'Move older indices to UltraWarm (S3-backed warm storage) or Cold storage' }, { id: 'C', text: 'Delete logs after 7 days' }, { id: 'D', text: 'Compress OpenSearch indices' }], correct: ['B'], explanation: 'OpenSearch has tiered storage: Hot (SSD, full performance), UltraWarm (S3-backed with caching, 90% cheaper than hot), and Cold (S3-backed, lowest cost, requires detach/attach to query). Use Index State Management (ISM) to automatically move indices through tiers.', distractors: { A: 'Deleting logs violates the 90-day retention requirement.', C: 'Exporting to S3 removes data from OpenSearch — requires Athena to query, not OpenSearch Dashboards.', D: 'Compression reduces index size — doesn\'t match the cost savings of moving to S3-backed tiers.' } },
  { id: 'd3-ana-037', domain: 3, topics: ['Glue', 'DataBrew', 'visual ETL'], type: 'single', stem: 'A data analyst (not a developer) needs to clean, normalize, and transform datasets without writing code. What AWS service provides a visual, no-code data preparation tool?', options: [{ id: 'A', text: 'Amazon SageMaker Data Wrangler' }, { id: 'B', text: 'AWS Glue ETL with Spark' }, { id: 'C', text: 'AWS Glue DataBrew' }, { id: 'D', text: 'AWS Glue Studio' }], correct: ['C'], explanation: 'AWS Glue DataBrew is a visual data preparation tool. Analysts can explore datasets, apply 250+ transformations visually (cleaning, normalizing, pivoting, merging), and schedule transformation jobs — no coding required. Data from S3, Glue Catalog, or database sources.', distractors: { A: 'Glue Studio provides a visual ETL interface but uses Spark and is more developer-oriented.', C: 'SageMaker Data Wrangler is for ML feature engineering — DataBrew is for general data preparation.', D: 'Glue ETL with Spark requires coding — not suitable for non-technical analysts.' } },
  { id: 'd3-ana-038', domain: 3, topics: ['Redshift', 'sort keys', 'zone maps'], type: 'single', stem: 'A Redshift table is frequently queried with WHERE event_date BETWEEN \'2024-01-01\' AND \'2024-01-31\'. What table configuration speeds up this date-range filter?', options: [{ id: 'A', text: 'Add a traditional index on event_date' }, { id: 'B', text: 'Use materialized views with date filters' }, { id: 'C', text: 'Partition the table by month' }, { id: 'D', text: 'Define event_date as the sort key' }], correct: ['D'], explanation: 'Redshift sort keys enable zone map pruning. Data blocks are stored sorted by the sort key. Each block has a min/max metadata record (zone map). For range queries, Redshift skips blocks that can\'t possibly match — similar to partition pruning. Compound sort keys for multi-column filters.', distractors: { A: 'Redshift doesn\'t have traditional B-tree indexes — sort keys are the Redshift equivalent.', C: 'Redshift doesn\'t have native table partitioning like PostgreSQL — sort keys + zone maps serve this purpose.', D: 'Materialized views precompute results — not optimal for arbitrary date ranges that change with each query.' } },
  { id: 'd3-ana-039', domain: 3, topics: ['Kinesis Data Firehose', 'format conversion', 'Parquet'], type: 'single', stem: 'Firehose receives JSON records and needs to deliver them to S3 as Parquet format for efficient Athena querying. What Firehose feature enables this without a Lambda function?', options: [{ id: 'A', text: 'Firehose format conversion' }, { id: 'B', text: 'S3 Object Lambda for format conversion' }, { id: 'C', text: 'Lambda transformation to Parquet' }, { id: 'D', text: 'Glue job post-delivery conversion' }], correct: ['A'], explanation: 'Firehose supports native format conversion from JSON to Parquet or ORC. Requires a schema registered in the Glue Data Catalog. Firehose converts records inline during delivery — no Lambda code needed. Enables efficient Athena queries directly from Firehose delivery.', distractors: { A: 'Lambda transformation is needed for custom logic — format conversion to Parquet/ORC is built into Firehose natively.', C: 'Post-delivery Glue conversion adds delay — Firehose native conversion is inline.', D: 'S3 Object Lambda transforms data during S3 GET requests — not during Firehose delivery.' } },
  { id: 'd3-ana-040', domain: 3, topics: ['EMR', 'S3 vs HDFS', 'storage'], type: 'single', stem: 'An EMR cluster stores working data in HDFS on cluster instances. When the cluster terminates, all data is lost. What architecture separates compute from storage for durability?', options: [{ id: 'A', text: 'Use S3 as the primary data store (EMR File System' }, { id: 'B', text: 'Use Reserved Instances for EMR' }, { id: 'C', text: 'Enable HDFS replication factor of 3' }, { id: 'D', text: 'Use EBS volumes attached to EMR instances' }], correct: ['A'], explanation: 'EMRFS allows EMR to use S3 as a replacement for HDFS. Data persists independently of the cluster lifecycle. Enables transient clusters: spin up for a job, write results to S3, terminate. No data loss, lower cost (no need to keep cluster running between jobs).', distractors: { A: 'EBS volumes are terminated with the cluster — doesn\'t provide persistence.', C: 'HDFS replication factor 3 protects against node failure within the cluster — not cluster termination.', D: 'Reserved Instances reduce cost — don\'t solve data persistence.' } },
  { id: 'd3-ana-041', domain: 3, topics: ['Athena', 'workgroups', 'cost control'], type: 'single', stem: 'Multiple teams use Athena in the same AWS account. Finance needs to track Athena costs per team and limit the amount of data each team can scan per query. What Athena feature enables this?', options: [{ id: 'A', text: 'S3 bucket policies per team' }, { id: 'B', text: 'IAM policies limiting Athena usage' }, { id: 'C', text: 'Create separate AWS accounts per team' }, { id: 'D', text: 'Athena Workgroups' }], correct: ['D'], explanation: 'Athena Workgroups provide per-team isolation. Configure data scan limits (prevent expensive queries), separate result locations, per-workgroup CloudWatch metrics (for cost allocation), and enforce encryption. Teams see only their workgroup\'s query history.', distractors: { A: 'Separate accounts provide stronger isolation but add management overhead — workgroups provide team-level isolation within one account.', C: 'S3 bucket policies control data access — not Athena query cost limits.', D: 'IAM policies control which Athena APIs a user can call — not query-level scan limits.' } },
  { id: 'd3-ana-042', domain: 3, topics: ['Firehose', 'error handling', 'S3 backup'], type: 'single', stem: 'A Firehose delivery stream sends records to Redshift. Some records fail to load (malformed SQL values). What happens to failed records?', options: [{ id: 'A', text: 'Failed records go to an SQS DLQ' }, { id: 'B', text: 'Failed records are discarded' }, { id: 'C', text: 'Firehose can deliver failed records to an S3 backup bucket' }, { id: 'D', text: 'Firehose retries indefinitely' }], correct: ['C'], explanation: 'Firehose supports S3 backup for failed delivery records. When delivery to Redshift (or other destinations) fails after retries, failed records are written to the S3 backup bucket with error metadata. Operators can inspect and reprocess failed records from S3.', distractors: { A: 'Firehose doesn\'t discard records silently — failed records go to S3 backup if configured.', C: 'Firehose has configurable retry duration (60-7,200 seconds) — not indefinite retry.', D: 'Firehose doesn\'t use SQS DLQ — S3 backup bucket is the failure destination.' } },
  { id: 'd3-ana-043', domain: 3, topics: ['Redshift', 'Serverless', 'on-demand'], type: 'single', stem: 'A company runs Redshift queries intermittently — several bursts per week with no activity in between. A provisioned cluster idles 80% of the time. What Redshift option eliminates idle cluster costs?', options: [{ id: 'A', text: 'Pause the Redshift cluster manually' }, { id: 'B', text: 'Amazon Redshift Serverless' }, { id: 'C', text: 'Use Redshift RA3 for storage/compute separation' }, { id: 'D', text: 'Schedule cluster pause during off-hours' }], correct: ['B'], explanation: 'Redshift Serverless provisions compute automatically when queries run and scales to zero between workloads. Charges in Redshift Processing Units (RPUs) × seconds. No cluster management, no idle capacity charges. Ideal for intermittent analytical workloads.', distractors: { A: 'Manual pause requires operational awareness — doesn\'t handle ad-hoc query bursts.', C: 'RA3 separates storage from compute for better scaling — still requires a running cluster; doesn\'t eliminate idle costs.', D: 'Scheduled pause requires knowing when queries run — misses unexpected query times.' } },
  { id: 'd3-ana-044', domain: 3, topics: ['Glue', 'streaming ETL', 'micro-batch'], type: 'single', stem: 'Real-time data from Kinesis needs to be cleaned, transformed, and written to S3 every 60 seconds. What AWS Glue capability handles streaming ETL?', options: [{ id: 'A', text: 'Lambda with Kinesis trigger' }, { id: 'B', text: 'Kinesis Data Analytics' }, { id: 'C', text: 'AWS Glue Streaming ETL' }, { id: 'D', text: 'AWS Glue batch jobs (triggered every 60 seconds)' }], correct: ['C'], explanation: 'Glue Streaming ETL supports continuous streaming jobs that read from Kinesis Data Streams or Kafka (MSK) and process data in micro-batches. Uses the same Glue Spark infrastructure as batch jobs. Handles transformations and writes to S3 or other destinations on configurable intervals.', distractors: { A: 'Triggering batch jobs every 60 seconds has cold start overhead — Streaming ETL runs continuously.', C: 'Lambda with Kinesis works for simple transforms — Glue Streaming ETL handles complex Spark transformations at scale.', D: 'Kinesis Data Analytics (Managed Flink) is purpose-built for real-time streaming — Glue Streaming ETL is also valid for Spark-based streaming.' } },
  { id: 'd3-ana-045', domain: 3, topics: ['analytics architecture', 'lambda architecture', 'kappa'], type: 'single', stem: 'A company needs both real-time dashboards (streaming) and historical batch analytics (batch) from the same data. What architectural pattern serves both needs from a single data platform?', options: [{ id: 'A', text: 'Use only real-time streaming for all queries' }, { id: 'B', text: 'Use only batch processing and cache results' }, { id: 'C', text: 'Run two separate systems with duplicate data ingestion' }, { id: 'D', text: 'Lambda Architecture: real-time stream (Kinesis → Flink → DynamoDB for hot data) + batch layer (Kinesis → S3 → Glue/EMR → Redshift for historical) with a serving layer that merges both' }], correct: ['D'], explanation: 'Lambda Architecture (the big data pattern, not AWS Lambda) uses three layers: Speed layer (real-time stream processing for low-latency recent data), Batch layer (historical reprocessing for accuracy), and Serving layer (merges both). Common AWS implementation: Kinesis for speed, S3/EMR for batch, Redshift/DynamoDB as serving.', distractors: { A: 'Duplicate ingestion is inefficient — unified streaming to S3 (Firehose) with Flink for real-time serves both layers from one stream.', C: 'Real-time only lacks historical reprocessing capability for corrections and audits.', D: 'Batch only has high latency — doesn\'t meet real-time dashboard requirements.' } },
]
